//! Reciprocal molecular connections for an intensity-measuring camera.
//!
//! In opposite travel frames sharing the same horizontal axis, reciprocity is
//! `M_reverse = A M_forward^T A`, `A = diag(1,1,-1,1)` (Germer 2017,
//! doi:10.1364/AO.56.009333, eq. 12). Thus a reciprocal camera walk launched
//! with unpolarized unit power retains the scalar detector covector in its
//! Stokes state: `response = camera^T A source`. This also retains circular
//! polarization generated by complex Fresnel amplitudes and noncommuting
//! reciprocal retarders. A simple reversal of the reference frame, which
//! changes both U and V, is not this time-reversal/adjoint relation.
//!
//! This restricted scalar contraction does not provide a full Mueller-valued
//! camera observation or support nonreciprocal magneto-optic elements.

use super::{PhaseFunction, PolarizedScatteringError, cross, depolarization, unit};
use crate::polarization::Stokes;
use crate::polarization::dielectric::transport::{BeamError, PolarizationFrame, PolarizedBeam};
use fs_math::det;

impl PhaseFunction {
    /// Molecular source-to-camera angular response, in inverse steradians.
    ///
    /// `camera_prefix` is the pre-collision beam of the original reciprocal
    /// camera walk, travelling FROM the camera TO this vertex. `source_frame`
    /// travels FROM the source TO the same vertex; `normalized_source` has
    /// intensity exactly one in that frame, as retained by a native polarized
    /// refractive bundle. The source scatters toward the reverse camera ray.
    ///
    /// The returned factor includes neither input's intensity. Multiply it by
    /// `camera_prefix.power().i`, calibrated source irradiance on a plane
    /// perpendicular to source arrival, source-leg scattering survival, and
    /// the camera's native index-squared conversion. Keep those factors with
    /// their original radiometric owners, preferably logarithmic when needed.
    /// Camera free-flight sampling already supplies collision density and
    /// camera survival: neither belongs here. The sampled continuation phase
    /// PDF is also absent because this is a separately evaluated connection.
    ///
    /// Frames are rotated before contraction; Q/U/V are not discarded. Exact
    /// polarization extinction is a valid zero. A zero-intensity prefix cannot
    /// define a normalized response and refuses instead of hiding underflow.
    pub fn rayleigh_connection_factor(
        &self,
        camera_prefix: PolarizedBeam,
        source_frame: PolarizationFrame,
        normalized_source: Stokes,
    ) -> Result<f64, PolarizedScatteringError> {
        let delta = depolarization(self)?;
        if normalized_source.i != 1.0 || camera_prefix.power().i <= 0.0 {
            return Err(BeamError::InvalidStokes.into());
        }
        let incoming = source_frame.direction();
        let outgoing = camera_prefix.frame().direction().scale(-1.0);
        let perpendicular = cross(incoming, outgoing);
        let axis = if perpendicular.x == 0.0 && perpendicular.y == 0.0 && perpendicular.z == 0.0 {
            source_frame.horizontal()
        } else {
            unit(perpendicular)?
        };
        let source_plane = PolarizationFrame::try_new(incoming, axis)?;
        let camera_plane = PolarizationFrame::try_new(camera_prefix.frame().direction(), axis)?;
        let incident = normalized(source_frame.express_in(normalized_source, source_plane))?;
        let prefix = normalized(camera_prefix.power())?;
        let camera = normalized(camera_prefix.frame().express_in(prefix, camera_plane))?;
        let cosine = incoming.dot(outgoing).clamp(-1.0, 1.0);
        let scale = 3.0 / (8.0 * core::f64::consts::PI * (2.0 + delta));
        let perpendicular_power = 1.0 + incident.q;
        let parallel_power = (1.0 - incident.q) * cosine * cosine;
        // This is the existing Hansen--Travis Mueller response, factored to
        // preserve tiny p-polarized power near a dipole's 90-degree null.
        // Subtracting M00 and M01 would round that positive power to zero.
        let mut scattered = Stokes {
            i: scale * ((1.0 - delta) * (perpendicular_power + parallel_power) + 2.0 * delta),
            q: scale * (1.0 - delta) * (perpendicular_power - parallel_power),
            u: scale * 2.0 * (1.0 - delta) * cosine * incident.u,
            v: scale * 2.0 * (1.0 - 2.0 * delta) * cosine * incident.v,
        };
        if scattered.i == 0.0 {
            if perpendicular_power != 0.0 || cosine != 0.0 || delta != 0.0 {
                return Err(BeamError::NumericalRange.into());
            }
            return Ok(0.0);
        }
        let intensity = scattered.i;
        scattered = normalized(scattered)?;
        // Apply A to the physical outgoing source Stokes, and contract the two
        // normalized positive coherency states. Writing 1 + a dot b as a sum
        // of cone slack and squared lengths preserves crossed-polarizer zeros
        // without cancelling two nearly equal positive radiances.
        let a = [camera.q, camera.u, camera.v];
        let b = [scattered.q, -scattered.u, scattered.v];
        let slack_a = cone_slack(a)?;
        let slack_b = cone_slack(b)?;
        let sum_squares = a
            .into_iter()
            .zip(b)
            .map(|(a, b)| (a + b) * (a + b))
            .sum::<f64>();
        let overlap = 0.5 * (slack_a + slack_b + sum_squares);
        let factor = intensity * overlap;
        if !factor.is_finite() || factor < 0.0 || (overlap > 0.0 && factor == 0.0) {
            return Err(BeamError::NumericalRange.into());
        }
        Ok(factor)
    }
}

// Normalize only finite admitted Stokes states, removing cone overshoot at
// roundoff scale. The tolerance is relative to I, including tiny intensities;
// it cannot turn a materially unphysical source into a valid optical model.
fn normalized(input: Stokes) -> Result<Stokes, BeamError> {
    if input.i <= 0.0 || Stokes::try_new(input.i, input.q, input.u, input.v).is_none() {
        return Err(BeamError::InvalidStokes);
    }
    let mut result = Stokes {
        i: 1.0,
        q: input.q / input.i,
        u: input.u / input.i,
        v: input.v / input.i,
    };
    let degree = det::hypot(det::hypot(result.q, result.u), result.v);
    if degree > 1.0 {
        result.q /= degree;
        result.u /= degree;
        result.v /= degree;
    }
    Ok(result)
}

fn cone_slack(polarization: [f64; 3]) -> Result<f64, BeamError> {
    let degree = det::hypot(
        det::hypot(polarization[0], polarization[1]),
        polarization[2],
    );
    if !degree.is_finite() || degree > 1.0 + 16.0 * f64::EPSILON {
        return Err(BeamError::NumericalRange);
    }
    Ok((1.0 - degree.min(1.0)) * (1.0 + degree.min(1.0)))
}

